/** Authored narrative is separate from machine evidence; a missing translation blocks publication. */
export function humanObservation(causalCase: FormalCase): string {
  const text = causalCase.narrative || observations[causalCase.id];
  if (!text) throw new Error(`Нет narrative для ${causalCase.id}`);
  return text;
}

